import type { ComponentProps, MouseEvent, ReactNode } from 'react'
import { Icon, type IconName } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './Alert.module.css'

export interface AlertProps extends Omit<ComponentProps<'div'>, 'title'> {
  variant?: 'info' | 'success' | 'warning' | 'danger'
  appearance?: 'subtle' | 'outlined' | 'solid'
  title?: ReactNode
  /** Replaces the variant's icon; `false` shows none. */
  icon?: ReactNode | false
  /** Buttons or links under the message, e.g. "Retry". */
  action?: ReactNode
  /** Shows a close button that calls this. The alert does not hide itself: remove it when this fires. */
  onClose?: (event: MouseEvent<HTMLButtonElement>) => void
  /** Accessible name of the close button. */
  closeLabel?: string
  /**
   * Announce the alert when it appears. `danger` and `warning` interrupt
   * (`role="alert"`), the others wait their turn (`role="status"`). Leave it
   * off for an alert that is on the page from the start.
   */
  isLive?: boolean
}

const icons: Record<NonNullable<AlertProps['variant']>, IconName> = {
  info: 'info-filled',
  success: 'success-filled',
  warning: 'warning-filled',
  danger: 'danger-filled',
}

export function Alert({
  variant = 'info',
  appearance = 'subtle',
  title,
  icon,
  action,
  onClose,
  closeLabel = 'Dismiss',
  isLive = false,
  className,
  children,
  ...props
}: AlertProps) {
  const urgent = variant === 'danger' || variant === 'warning'
  return (
    <div
      role={isLive ? (urgent ? 'alert' : 'status') : undefined}
      className={cn(styles.alert, styles[variant], styles[appearance], className)}
      {...props}
    >
      {icon !== false && (
        <span className={styles.icon} aria-hidden="true">
          {icon ?? <Icon name={icons[variant]} />}
        </span>
      )}
      <div className={styles.body}>
        {title && <div className={styles.title}>{title}</div>}
        {children && <div className={styles.description}>{children}</div>}
        {action && <div className={styles.action}>{action}</div>}
      </div>
      {onClose && (
        <button type="button" aria-label={closeLabel} className={styles.close} onClick={onClose}>
          <Icon name="close" />
        </button>
      )}
    </div>
  )
}

.alert {
  display: flex;
  align-items: flex-start;
  /* Atlassian's section message: 16px around and 16px from the icon to the
     text. The padding gives back the border's pixel, so the content sits
     16px from the edge. */
  gap: var(--space-group);
  box-sizing: border-box;
  padding: calc(var(--space-group) - var(--border-width));
  /* Always present, transparent unless outlined, so appearances never
     shift the layout. */
  border: var(--border-width) solid transparent;
  border-radius: var(--radius-lg);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
}

/* One rule per variant, the same four colours as Tag. */
.info {
  --alert-solid: var(--color-background-info-bold);
  --alert-on-solid: var(--color-text-info-inverse);
  --alert-subtle: var(--color-background-info);
  --alert-text: var(--color-text-info);
}
.success {
  --alert-solid: var(--color-background-success-bold);
  --alert-on-solid: var(--color-text-success-inverse);
  --alert-subtle: var(--color-background-success);
  --alert-text: var(--color-text-success);
}
.warning {
  --alert-solid: var(--color-background-warning-bold);
  --alert-on-solid: var(--color-text-warning-inverse);
  --alert-subtle: var(--color-background-warning);
  --alert-text: var(--color-text-warning);
}
.danger {
  --alert-solid: var(--color-background-danger-bold);
  --alert-on-solid: var(--color-text-danger-inverse);
  --alert-subtle: var(--color-background-danger);
  --alert-text: var(--color-text-danger);
}

/* Subtle and outlined keep the message in --color-text: a paragraph in
   the variant's text colour is tiring to read. The colour goes on the icon
   and the title, which is where the eye lands first. */
.subtle {
  background: var(--alert-subtle);
  color: var(--color-text);
}
.outlined {
  border-color: var(--alert-text);
  background: var(--color-surface);
  color: var(--color-text);
}
.subtle .icon,
.subtle .title,
.subtle .close,
.outlined .icon,
.outlined .title,
.outlined .close {
  color: var(--alert-text);
}
.solid {
  background: var(--alert-solid);
  color: var(--alert-on-solid);
}

.icon {
  display: inline-flex;
  flex-shrink: 0;
  /* One line of body text tall, so it sits on the title's line.
     --leading-body is a ratio, so it is multiplied by 1em. */
  font-size: calc(var(--leading-body) * 1em);
}

.body {
  display: grid;
  flex: 1;
  /* 8px between title, description and actions, as Atlassian's. */
  gap: var(--space-inline);
  min-inline-size: 0;
}

.title {
  font-weight: 600;
}

.action {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-inline);
}

.close {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  /* Flush with the 16px padding and top-aligned with the icon, as Figma. */
  margin: 0;
  inline-size: var(--box-sm);
  block-size: var(--box-sm);
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: inherit;
  font-size: var(--icon-md);
  cursor: var(--cursor-button);
}

/* A tint of the alert's own text colour, so hover reads on every variant
   and appearance. */
.close:hover {
  background: color-mix(in oklch, currentColor 15%, transparent);
}

.close:focus-visible {
  outline: var(--focus-width) solid var(--color-border-focused);
  outline-offset: var(--focus-offset-inset);
}

@media (pointer: coarse) {
  .close::before {
    content: '';
    position: absolute;
    inset: 50% auto auto 50%;
    inline-size: var(--target-coarse);
    block-size: var(--target-coarse);
    translate: -50% -50%;
  }
}
